-- CREATE DYNAMIC TABLE clauses
-- https://docs.snowflake.com/en/sql-reference/sql/create-dynamic-table

CREATE DYNAMIC TABLE dt_scheduler
TARGET_LAG = '5 minutes'
SCHEDULER = DISABLE
WAREHOUSE = wh
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_scheduler_enable
TARGET_LAG = '5 minutes'
SCHEDULER = ENABLE
WAREHOUSE = wh
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_frozen
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
FROZEN WHERE (ts < '2020-01-01')
AS
SELECT a, ts FROM b;

CREATE DYNAMIC TABLE dt_execute_as_user
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
EXECUTE AS USER my_user
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_execute_as_user_roles
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
EXECUTE AS USER my_user USE SECONDARY ROLES ALL
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_execute_as_user_named_roles
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
EXECUTE AS USER my_user USE SECONDARY ROLES role_a, role_b
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_row_timestamp
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
ROW_TIMESTAMP = TRUE
AS
SELECT a FROM b;

CREATE DYNAMIC TABLE dt_refresh_using
TARGET_LAG = '5 minutes'
WAREHOUSE = wh
REFRESH USING (INSERT INTO SELF SELECT a FROM b);

CREATE OR REPLACE DYNAMIC TABLE dt_refresh_using_merge
TARGET_LAG = DOWNSTREAM
WAREHOUSE = wh
REFRESH USING (MERGE INTO SELF USING b ON SELF.a = b.a WHEN MATCHED THEN UPDATE SET SELF.a = b.a);

CREATE DYNAMIC ICEBERG TABLE dt_iceberg
TARGET_LAG = '20 minutes'
WAREHOUSE = wh
EXTERNAL_VOLUME = 'vol'
CATALOG = 'SNOWFLAKE'
BASE_LOCATION = 'loc'
TARGET_FILE_SIZE = 'AUTO'
AS
SELECT a FROM b;

CREATE DYNAMIC ICEBERG TABLE dt_iceberg_full
TARGET_LAG = '20 minutes'
WAREHOUSE = wh
EXTERNAL_VOLUME = 'vol'
CATALOG = 'SNOWFLAKE'
BASE_LOCATION = 'loc'
TARGET_FILE_SIZE = '128MB'
PATH_LAYOUT = HIERARCHICAL
ICEBERG_VERSION = 3
PARTITION BY (a, TO_DATE(ts))
AS
SELECT a, ts FROM b;
